using System; namespace HDFCSmartGateway.Services { public class HdfcSettings { public string BaseUrl=E("HDFC_BASE_URL","https://smartgateway.hdfcuat.bank.in"), MerchantId=E("HDFC_MERCHANT_ID","SG6695"), ApiKey=E("HDFC_API_KEY",""), ClientId=E("HDFC_PAYMENT_PAGE_CLIENT_ID","hdfcmaster"), ReturnUrl=E("HDFC_RETURN_URL",""), SessionPath=E("HDFC_SESSION_PATH","/session"), StatusPath=E("HDFC_ORDER_STATUS_PATH","/orders/{orderId}"), RoutingHeader=E("HDFC_ROUTING_HEADER_NAME","x-routing-id"); public string Validate(){Uri u;if(!Uri.TryCreate(BaseUrl,UriKind.Absolute,out u)||u.Scheme!="https"||u.Host!="smartgateway.hdfcuat.bank.in")return "Only the HDFC UAT HTTPS host is allowed.";if(String.IsNullOrWhiteSpace(ApiKey)||String.IsNullOrWhiteSpace(MerchantId)||String.IsNullOrWhiteSpace(ClientId))return "Configure HDFC_API_KEY, HDFC_MERCHANT_ID and HDFC_PAYMENT_PAGE_CLIENT_ID.";return null;}static string E(string k,string d){var v=Environment.GetEnvironmentVariable(k);return String.IsNullOrWhiteSpace(v)?d:v;} } }